def L(a,z):return '「'+''.join(T[a-1:z])+'」'
B=[
dict(a=1,z=5,star=3,lit=L(1,5),
key=[('公平','H4941','mishpat','公平、審判'),('公義','H6666','utsedaqah','公義、正直'),('寄居的','H1616','vegger','外來的、寄居者'),('孤兒','H3490','yatom','無父的孩子'),('寡婦','H490','almanah','寡婦')],
gram=['**{H4941}**（mishpat）與**{H6666}**（tsedaqah）：這兩個字常常**並列**，是聖經**社會正義的核心**。公平是**制度**，公義是**心**；兩樣缺一不可。','**{H1616}**（ger）、**{H3490}**（yatom）、**{H490}**（almanah）：**寄居的、孤兒、寡婦**，是聖經裡**最容易被欺壓的三種人**，在申命記與先知書中反覆出現。**一個社會的好壞，要看它怎樣對待這三種人。**'],
exp=['二十二章一節，神叫先知**下到猶大王的宮中**。上一章，神對王家說了公義的指令；這一章，**先知親自走進王宮**，把話說到**王的面前**。這不是在廣場上喊話，而是**走進權力的中心**。**傳神話語的人，有時需要走進最不歡迎他的地方。**','三節是整章的**核心指令**：你們要施行公平和公義，拯救被搶奪的脫離欺壓人的手，不可虧負寄居的和孤兒寡婦，不可以強暴待他們，也不可流無辜人的血。注意這一連串的動詞：**施行、拯救、不可虧負、不可強暴、不可流血**。神對王的要求，**不是宗教的，而是社會的**。','四、五節是**兩條路**：若認真行，大衛的寶座就必存立，**君王仍然可以坐車騎馬進城**；若不聽，**神指著自己起誓，這城必變為荒場**。神的誓言，可以是**祝福的誓言**，也可以是**審判的誓言**，端看人怎樣回應。']),
dict(a=6,z=9,star=2,lit=L(6,9),
key=[('基列','H1568','gilad','基列山區（豐美的牧地）'),('黎巴嫩','H3844','levanon','黎巴嫩山，以香柏樹聞名'),('香柏樹','H730','arazeikha','香柏樹'),('毀滅的人','H7843','mashkhitim','毀滅者'),('約','H1285','berit','約、盟約')],
gram=['**{H730}**（erez，香柏樹）：香柏樹是**所羅門建殿的材料**，象徵**王家的榮華**。神說要**砍下佳美的香柏樹**，是說**王家最引以為傲的，要被拿走**。','**{H1285}**（berit，約）：九節給了**全章最簡單的答案**：因為離棄了耶和華他們神的**約**。審判的原因，**不是別的，而是約**。'],
exp=['六節神用兩個地名描寫王家：**我看你如基列，如黎巴嫩頂**。基列是豐美的牧地，黎巴嫩是**雄偉的高山**。這是**神對王家的看重**：祂**曾經**這樣看他們。接著是一個**轉折**：然而，我必使你變為曠野。**從黎巴嫩到曠野**，是整段最大的**落差**。','七節的畫面很具體：**砍下佳美的香柏樹，扔在火中**。香柏樹是**王宮的建材**（十四節），**他們最引以為榮的，就是被燒掉的**。','八、九節是整段的**回聲**：過路的列國人問：耶和華為何向這大城如此行呢？答案很簡單：**是因離棄了耶和華他們神的約，事奉敬拜別神**。**審判的原因，連外邦人都看得懂。**']),
dict(a=10,z=12,star=2,lit=L(10,12),
key=[('哭號','H1058','tivku','哭泣'),('悲傷','H5110','tanudu','搖頭哀悼'),('沙龍','H7967','shallum','（人名，即約哈斯）'),('約西亞','H2977','yoshiyahu','（人名，猶大好王）'),('被擄去的地方','H1540','higlu','被擄、被流放')],
gram=['**{H5110}**（nud，搖頭）：這個字描寫**搖頭哀悼**，是東方人**表達同情**的動作。神說**不要為死人搖頭**，卻要**為活著的流亡者哭**。','**{H7967}**（Shallum，沙龍）：沙龍就是**約哈斯**（王下二十三30–34），**約西亞的兒子**，登基三個月，就被埃及王尼哥**擄到埃及死了**。'],
exp=['十節是**整章最令人意外的一句話**：不要為死人哭號，卻要為離家出外的人大大哭號。**死了的人，已經安息；活著被擄的人，才是真正的痛苦**。他永遠不能再回來，也不能再看見自己的本國。**流亡，比死亡更令人心碎。**','十一、十二節點出這個人是**沙龍**，也就是約哈斯，約西亞的兒子。**約西亞是猶大最敬畏神的王**，可是他的兒子**一個比一個差**。**好的父親，不一定有好的兒子**。這提醒我們：信仰，**不能被繼承，只能被選擇**。']),
dict(a=13,z=14,star=3,lit=L(13,14),
key=[('有禍了','H1945','hoi','哀哉、禍哉'),('不義','H6664','be lo tsedeq','不義（沒有公義）'),('白白','H2600','khinnam','白白地、不給報酬'),('工價','H6467','poalo','工錢、作工的報酬'),('香柏木','H730','baerez','香柏木')],
gram=['**{H1945}**（hoi，有禍了）：這是**先知的哀歌式的呼聲**，原本用在**葬禮**，就是「哀哉」。神**為還活著的約雅敬哀哭**，因為**他的下場已經註定**。','**{H2600}**（khinnam，白白）：這個字意思是**不付代價**。王**白白使用人的手工，不給工價**。這與**申命記二十四章十四至十五節**直接相關：**不可剋扣窮苦人的工價**。'],
exp=['十三節是**整章的一聲驚雷**：那行不義蓋房、行不公造樓、白白使用人的手工不給工價的有禍了！這是**對約雅敬王**說的。他在國家危急之時，**大興土木，建造豪華的宮殿**，卻**不給工人工錢**。**他的宮殿，是用窮人的血汗砌成的。**','十四節描寫他的**宮殿**：廣大的房、寬敞的樓、**香柏木的護牆板**、**丹色的油漆**。這是**奢華的描寫**。**他的房子很漂亮，他的心卻很空。**這提醒我們：**一棟大房子，不等於一個好王；一份好的工作成果，不能由不義的手段換來。**']),
dict(a=15,z=17,star=3,lit=L(15,17),
key=[('爭勝','H8474','mithareh','競爭、比較'),('施行公平和公義','H4941','mishpat utsedaqah','公平與公義'),('伸冤','H1777','din','審理、伸冤'),('認識','H1847','hadaat','認識、知道'),('貪婪','H1215','betsa','不義之財、貪婪')],
gram=['**{H1847}**（daat，認識）：十六節的**「認識我」**，是**整章最重要的定義**。**認識神，不是知識，而是為窮人伸冤**。這與**耶利米書九章二十四節**互相呼應。','**{H1215}**（betsa，貪婪）：這個字是**不義之財**。十七節說王的**眼與心**專顧**貪婪**：他的眼睛**只看見利益**，**看不見人**。'],
exp=['十五節是一個**反問**：難道你作王是在乎造香柏木樓房爭勝嗎？**他在跟別人比**：誰的房子更大、更華麗。神說，你**父親約西亞**，豈不是也吃也喝、也施行公平和公義嗎？**那時他得了福樂**。**好王不是不享受，而是享受的同時，仍然公義。**','十六節給了**聖經裡最重要的一個定義**：他為困苦和窮乏人伸冤，那時就得了福樂。**認識我不在乎此嗎？**這是神的**自問自答**：**認識神，就是為窮人伸冤**。不是讀很多書，不是參加很多聚會，**而是這個**。','十七節是**對比**：惟有你的眼和你的心專顧貪婪，流無辜人的血，行欺壓和強暴。**眼和心**，是**一個人最深的地方**。他的眼睛看的是**利益**，他的心想的是**貪婪**。**一個人的眼睛看什麼，他的人生就走向哪裡。**']),
dict(a=18,z=19,star=2,lit=L(18,19),
key=[('約雅敬','H3079','yehoyaqim','（人名，猶大王）'),('驢','H2543','khamor','驢'),('埋葬','H6900','qevurat','葬埋'),('拉出去','H5498','sakhov','拖拉'),('扔','H7993','hashlekh','拋棄、扔')],
gram=['**{H2543}**（khamor，驢）與**{H6900}**（qevurah，葬埋）：「埋驢一樣」是**說他沒有被好好安葬**。在古代近東，**不被好好埋葬，是極大的羞辱**。','**{H5498}**（sakhov，拖）與**{H7993}**（hashlekh，扔）：兩個動詞都是**對屍體的粗暴處理**：**拖出去，扔在城門外**。**一個王，最後沒有人為他哀哭。**'],
exp=['十八、十九節是**對約雅敬的判決**：人必不為他舉哀，說哀哉，我的哥哥；他被埋葬，好像埋驢一樣，要拉出去扔在耶路撒冷的城門之外。這是**最羞辱的結局**。**一個建造豪華宮殿的王，連一個舉哀的人都沒有。**','這是一個很嚴肅的提醒：**人生的成功，不在於蓋了多大的房子，而在於有多少人真心為你的離去哀悼**。約雅敬**建造了宮殿**，卻**沒有建立關係**。**人比事重要，關係比東西重要。**']),
dict(a=20,z=23,star=2,lit=L(20,23),
key=[('哀號','H6817','utseqi','呼喊、哀號'),('巴珊','H1316','bashan','巴珊（山區）'),('搭窩','H7077','mequnnenet','築巢、安居'),('疼痛','H2256','khavalim','疼痛、陣痛'),('興盛','H7962','beshalvotaikh','安逸、順遂')],
gram=['**{H7077}**（qanan，築巢）：「在香柏樹上搭窩」是說**住得又高又舒適**，以為**永遠安全**。神說：**痛苦會臨到**，像**產婦的陣痛**。','**{H7962}**（shalvah，興盛）：二十一節說「**你興盛的時候，我對你說話；你卻說：我不聽**」。**興盛，往往是聽不見神的季節**。'],
exp=['二十到二十三節，**對象變成耶路撒冷**（或王的母后）。神叫她**上黎巴嫩、巴珊、亞巴琳**，三個山頂哀號，因為她**所親愛的（盟友）都毀滅了**。**她從高處，看見自己的下場。**','二十一節是**一句很痛的話**：你興盛的時候，我對你說話；你卻說：我不聽。你自幼年以來總是這樣。**不是神沒有說話，而是人不聽**。注意**「興盛的時候」**：**順境，往往是人最聽不見神的時候。**','二十三節是**一個很柔和的畫面**：你這住黎巴嫩、在香柏樹上搭窩的，有痛苦臨到你，好像疼痛臨到產難的婦人。**那個在高處築巢的人，最後只剩下疼痛。**']),
dict(a=24,z=27,star=3,lit=L(24,27),
key=[('哥尼雅','H3659','konyahu','（人名，約雅斤）'),('戒指','H2368','khotam','印、印戒'),('右手','H3225','yemini','右手'),('摘下來','H5423','etqenkha','拔掉、扯下'),('永生','H2416','khai','我的永生（神的起誓）')],
gram=['**{H2368}**（khotam，印戒）：印戒是**王的權柄的記號**，**蓋在文件上，代表王的權威**。神說哥尼雅是我右手上的印戒，是**說他曾經是神手中最親近的權柄**。','**{H2416}**（khai，永生）：「我憑我的永生起誓」是**神最重的起誓**：**以祂自己的生命為保證**。神**說到做到**，這是**神的決定，不可挽回**。'],
exp=['二十四節是**整章最有分量的一節**：哥尼雅雖是我右手上帶印的戒指，我憑我的永生起誓，也必將你從其上摘下來。**印戒**，是王權的象徵，**戴在右手上，是最貴重的位置**。神**親手把他摘下來**。**神揀選的，也可以把他放下。**','二十五到二十七節很具體：**交給巴比倫王**，**被趕到別國**，**死在那裡**，**心中甚想歸回之地，必不得歸回**。**最痛的是「甚想歸回」，卻「必不得歸回」。**這是**流亡者最深的渴望，也是最深的痛苦**。']),
dict(a=28,z=30,star=3,lit=L(28,30),
key=[('輕看','H959','nivzeh','被藐視'),('破壞的器皿','H5310','nafuts','破碎的'),('無子','H6185','ariri','無子女的'),('寫明','H3789','ketuvu','寫下來、記錄'),('得亨通','H6743','yitslakh','成功、亨通'),('治理','H4910','umoshel','統治')],
gram=['**{H6185}**（ariri，無子）：這個字不一定是「完全沒有孩子」，也可以是**「沒有一個後裔能繼承王位」**。哥尼雅其實**有後裔**（代上三17–18），可是**沒有一個能坐在大衛的寶座上**。','**{H3789}**（katav，寫明）：神說「要**寫明**這人」，**是把他的下場，記錄在案**，作為後人的警戒。**這是一份公開的見證**。'],
exp=['二十八節問了兩個問題：**哥尼雅這人是被輕看、破壞的器皿嗎？是無人喜愛的器皿嗎？**這是**神的問題，也是百姓的問題**。他是不是一個**壞掉的瓦器**，**沒有人要的**？我們可以想起十八、十九章的窯匠。**神沒有說答案，而是讓我們思考。**','二十九節是一個**很有力的呼喊**：地啊，地啊，地啊，當聽耶和華的話！**連呼三次**，像是**向天地作見證**。這是**舊約最激烈的呼籲之一**：**人不聽，就叫地來聽**。','三十節是**王室的終結宣告**：要寫明這人算為無子，是平生不得亨通的；因為他後裔中再無一人得亨通，能坐在大衛的寶座上治理猶大。**這節的意思是：哥尼雅的後代，沒有一個能繼承大衛的寶座。**這給後面的彌賽亞盼望**留下一個很大的問題**：**大衛的寶座，該怎麼繼承？**（見議題）']),
]
